<script lang="ts">
 import{onMount}from"svelte";import{commandStore,type ShellCommand}from"../../appshell/lib/commands-core";import{openWindow,setSpotlightOpen,shellStore}from"../../appshell/lib/store";import type{AppDescriptor}from"../types";
 let{apps}:{apps:AppDescriptor[]}=$props();let v=$state(0),cv=$state(0),q=$state("");onMount(()=>{const a=shellStore.subscribe(()=>v++),b=commandStore.subscribe(()=>cv++);return()=>{a();b()}});let open=$derived((v,shellStore.getSpotlightOpen()));let commands=$derived((cv,commandStore.get()));let items=$derived.by(()=>{const n=q.toLowerCase();const appItems:ShellCommand[]=apps.filter(a=>!a.noDock).map(a=>({id:`app:${a.id}`,label:`Open ${a.title}`,hint:"App",keywords:a.tags?.join(" "),run:()=>openWindow(a.id,a.title,a.defaultSize,undefined,{multi:a.multi})}));return[...appItems,...commands].filter(x=>!n||`${x.label} ${x.keywords??""}`.toLowerCase().includes(n)).slice(0,16)});function run(c:ShellCommand){c.run();setSpotlightOpen(false);q=""}
</script>
{#if open}<div class="veil" role="presentation" onclick={()=>setSpotlightOpen(false)}><dialog open aria-label="Command palette" onclick={e=>e.stopPropagation()} onkeydown={e=>e.stopPropagation()}><input aria-label="Search commands" placeholder="Search apps and commands" bind:value={q}/><ul>{#each items as c (c.id)}<li><button onclick={()=>run(c)}><span>{c.label}</span><small>{c.hint??"Action"}</small></button></li>{/each}</ul></dialog></div>{/if}
<style>.veil{position:absolute;inset:0;z-index:950;display:flex;justify-content:center;padding-top:12vh;background:#0004;backdrop-filter:blur(7px)}dialog{width:min(620px,92vw);height:max-content;max-height:65vh;overflow:auto;background:#191919e8;color:white;border:1px solid #ffffff2e;border-radius:16px;box-shadow:0 28px 90px #0009}input{width:100%;box-sizing:border-box;padding:15px 17px;background:transparent;color:white;border:0;border-bottom:1px solid #ffffff18;font-size:1rem;outline:0}ul{list-style:none;margin:0;padding:7px}button{width:100%;display:flex;justify-content:space-between;gap:12px;padding:10px;border:0;border-radius:9px;background:transparent;color:inherit;text-align:left}button:hover{background:#ffffff14}small{color:#aaa}</style>
